extension JSONMapValue {
  @inline(__always)
  var isNull: Bool {
    return self.is(.nullKeyword)
  }

  @inline(__always)
  func asBool() -> Bool? {
    if self.is(./*c*/trueKeyword) {
      return true
    }
    if self.is(.falseKeyword) {
      return false
    }
    return nil
  }
}
